import type { INodeProperties } from 'n8n-workflow';
import { describe, expect, it } from 'vitest';
import schema from './fixtures/inventree-api.json';
import { allOperations, evaluate, node, rl } from './helpers/routing';

/**
 * Schema conformance: every request the node can send must exist in
 * InvenTree's published OpenAPI schema (fixture generated by
 * `scripts/generate-schema-fixture.ts`). This walks every operation rather
 * than sampling, so a guessed URL, method or field name fails here.
 */

type Endpoint = { query: string[]; body: string[]; bodyItems?: string[] };
const paths = schema.paths as Record<string, Record<string, Endpoint>>;

/** `=/part/{{$parameter["partId"]}}/` -> `/part/{id}/` */
function template(url: string): string {
	return url.replace(/^=/, '').replace(/\{\{[^}]*\}\}/g, '{id}');
}

/** Query parameters a property sends through `routing.send` (e.g. Limit -> `limit`). */
function sendQueryKeys(resource: string, operation: string): string[] {
	return node.description.properties
		.filter((property: INodeProperties) => {
			const show = property.displayOptions?.show;
			return show?.resource?.includes(resource) && show?.operation?.includes(operation);
		})
		.map((property) => property.routing?.send)
		.filter((send) => send?.type === 'query')
		.map((send) => send?.property as string);
}

const operations = allOperations();

describe('schema conformance (InvenTree API ' + schema.apiVersion + ')', () => {
	it('covers every operation of the node', () => {
		// Part 5 + Stock Item 9 + BOM Item 5 + Purchase Order 10
		expect(operations.length).toBe(29);
	});

	it.each(operations.map((o) => [`${o.resource}.${o.operation}`, o] as const))(
		'%s uses an endpoint, method and fields that exist in the schema',
		(_, { resource, operation, routing }) => {
			const url = template(routing.request.url);
			const method = routing.request.method.toLowerCase();
			const endpoint = paths[url]?.[method];
			expect(endpoint, `${method.toUpperCase()} ${url}`).toBeDefined();

			expect(url.endsWith('/'), `${url} must end with a slash`).toBe(true);

			for (const key of Object.keys(routing.request.body ?? {})) {
				expect(endpoint.body, `body key ${key}`).toContain(key);
			}

			const queryKeys = [
				...Object.keys(routing.request.qs ?? {}),
				...sendQueryKeys(resource, operation),
			];
			if (routing.operations?.pagination) {
				queryKeys.push('limit', 'offset');
			}
			for (const key of queryKeys) {
				expect(endpoint.query, `query key ${key}`).toContain(key);
			}
		},
	);

	it.each(['addStock', 'removeStock', 'countStock', 'transfer'])(
		'stock %s sends adjustment items whose keys exist in the schema',
		(operation) => {
			const routing = operations.find(
				(o) => o.resource === 'stockItem' && o.operation === operation,
			)!.routing;
			const endpoint = paths[template(routing.request.url)].post;
			const items = evaluate(
				{
					resource: 'stockItem',
					operation,
					stockItemId: rl('7'),
					quantity: 2,
					destination: rl('3'),
				},
				routing.request.body?.items,
			) as Array<Record<string, unknown>>;
			expect(items).toHaveLength(1);
			for (const key of Object.keys(items[0])) {
				expect(endpoint.bodyItems, `items[] key ${key}`).toContain(key);
			}
		},
	);
});
